<template>
  <section v-loading="loading" class="shared-return-panel">
    <el-alert v-if="error" :title="error" type="error" :closable="false" /><el-empty v-if="!loading&&!data.bound&&!error" description="当前单据尚无共同退回包裹" /><template v-if="data.bound">
      <div class="heading"><div><h3>共同退回包裹 · {{ data.parcel.parcel_sn }}</h3><p class="hint">{{ data.parcel.carrier_code }} / {{ data.parcel.waybill }} · 接收仓 {{ data.parcel.store_code }} · {{ data.members.length }} 份售后来源</p></div><el-button size="small" @click="load">刷新共同进度</el-button></div>
      <div class="summary"><article><span>整包应退</span><strong>{{ totals.quantity }} 件</strong></article><article><span>整包实收</span><strong>{{ totals.accepted_quantity }} 件</strong></article><article><span>整包已入库</span><strong>{{ totals.posted_quantity }} 件</strong></article><article><span>待归属回传</span><strong>{{ pending.length }} 条</strong></article></div>
      <p v-if="data.document">实际共同退货入库单 <strong>{{ data.document.return_sn }}</strong> · {{ dispatchLabel }}<span class="hint"> · 仓库受理 {{ data.document.external_order||'尚未确认' }}</span></p><p v-else>尚未下发仓库 · 最后新增后的归集到期 {{ data.parcel.dispatch_after }}<span class="hint"> · 私有来源台账不单独发给仓库</span></p>
      <el-table :data="data.members" size="small" row-key="id"><el-table-column label="售后归属" min-width="280"><template slot-scope="s"><el-tag size="mini" :type="s.row.owner_kind==='EXCHANGE'?'':'warning'">{{ s.row.owner_kind==='EXCHANGE'?'换货':'退款' }}</el-tag> {{ s.row.owner_sn }}<el-tag v-if="s.row.current" size="mini" type="success">当前来源</el-tag><div class="hint">平台子单 {{ s.row.platform_oid }} · 仓库行号 {{ s.row.id }}</div></template></el-table-column><el-table-column prop="sku_sn" label="实际退回SKU" min-width="180" /><el-table-column prop="quantity" label="应退" width="80" /><el-table-column prop="accepted_quantity" label="已实收" width="90" /><el-table-column prop="posted_quantity" label="已入库" width="90" /></el-table>
      <div class="toolbar"><el-button v-if="canAct" size="small" @click="openAction(data.document?'query':'dispatch')">{{ data.document?'查询原仓库单':'确认整包下发' }}</el-button><el-button v-if="canAct&&data.document&&data.document.dispatch_state==='FAILED'" size="small" @click="openAction('retry')">核对后重试原单</el-button><el-button v-if="canAct&&data.document&&data.document.cancel_state==='NONE'" size="small" @click="openAction('cancel')">核对并截停整包</el-button><span v-if="!canAct" class="hint">共同操作须具备本包全部售后类型的处理权限。</span></div>
      <el-table v-if="data.receipts.length" :data="data.receipts" size="small"><el-table-column prop="message_id" label="仓库回传" min-width="170" /><el-table-column label="归属处理" width="150"><template slot-scope="s">{{ s.row.state==='ALLOCATED'?(s.row.allocation_method==='AUTO'?'已自动分配':'已人工分配'):s.row.state==='REJECTED'?'已拒绝该回传':'待逐行核对' }}</template></el-table-column><el-table-column prop="reason" label="原因 / 数量核对" min-width="260" /><el-table-column label="操作" width="210"><template slot-scope="s"><el-button v-if="s.row.state==='WAIT_ALLOCATION'&&canAct" type="text" @click="openReceipt(s.row)">核对实收分配</el-button><el-button v-if="s.row.state==='WAIT_ALLOCATION'&&canAct" type="text" @click="openRejection(s.row)">拒绝该回传</el-button></template></el-table-column></el-table>
    </template>
    <el-dialog :title="action==='allocate'?'逐行确认实收归属':actionLabels[action]" :visible.sync="visible" append-to-body width="min(1100px,96vw)" :close-on-click-modal="false">
      <el-alert title="本次操作范围包含整包的全部退款及换货来源；各自入库数量和原发货成本独立保留。" type="warning" :closable="false" />
      <template v-if="action==='allocate'"><p v-for="(line,i) in rawLines" :key="i" class="hint">原回传第{{ i+1 }}行 {{ line.sku }}：良品 {{ line.good }}、次品 {{ line.bad }}；已分配良品 {{ assigned(i,'good_qty') }}、次品 {{ assigned(i,'bad_qty') }}</p><el-table :data="form.allocations" size="small"><el-table-column label="原回传行" width="160"><template slot-scope="s"><el-select v-model="s.row.line_index" @change="s.row.member_id=undefined"><el-option v-for="(line,i) in rawLines" :key="i" :value="i" :label="'第'+(i+1)+'行 '+line.sku" /></el-select></template></el-table-column><el-table-column label="分到原售后来源" min-width="330"><template slot-scope="s"><el-select v-model="s.row.member_id" placeholder="选择明确的原来源"><el-option v-for="m in choices(s.row.line_index)" :key="m.id" :value="m.id" :label="(m.owner_kind==='EXCHANGE'?'换货 ':'退款 ')+m.owner_sn+' · 待收'+(Number(m.quantity)-Number(m.accepted_quantity))+'件'" /></el-select></template></el-table-column><el-table-column label="良品" width="150"><template slot-scope="s"><el-input-number v-model="s.row.good_qty" :min="0" :max="Number((rawLines[s.row.line_index]||{}).good)||0" :precision="0" controls-position="right" /></template></el-table-column><el-table-column label="次品" width="150"><template slot-scope="s"><el-input-number v-model="s.row.bad_qty" :min="0" :max="Number((rawLines[s.row.line_index]||{}).bad)||0" :precision="0" controls-position="right" /></template></el-table-column><el-table-column width="65"><template slot-scope="s"><el-button type="text" @click="form.allocations.splice(s.$index,1)">移除</el-button></template></el-table-column></el-table><el-button size="small" @click="form.allocations.push({line_index:0,member_id:undefined,good_qty:0,bad_qty:0})">增加分配行</el-button></template>
      <p class="hint">{{ (data.members||[]).map(m=>(m.owner_kind==='EXCHANGE'?'换货 ':'退款 ')+m.owner_sn+' / '+m.sku_sn+' / 应退'+m.quantity).join('；') }}</p>
      <el-form label-width="110px" style="margin-top:20px"><el-form-item label="核对结论"><el-input v-model.trim="form.reason" type="textarea" maxlength="500" /></el-form-item><el-form-item label="核对凭证"><el-input v-model.trim="form.evidence" maxlength="1000" placeholder="仓库回执 / 客服核对工单编号" /></el-form-item><el-form-item><el-checkbox v-model="form.confirmed_shared">已核对整包全部售后来源、数量与本次操作影响</el-checkbox></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!ready" @click="submit">确认{{ action==='allocate'?'按来源分配并入账':actionLabels[action] }}</el-button></span>
    </el-dialog>
  </section>
</template>
<script>
import request from '@/utils/request'
export default {
  props:{kind:{type:String,required:true},owner:{type:[Number,String],required:true},source:{type:[Number,String],required:true}},data:()=>({loading:false,busy:false,error:'',data:{bound:false,members:[],receipts:[]},visible:false,action:'',form:{allocations:[]},rawLines:[],sequence:0,actionLabels:{query:'查询原仓库单',dispatch:'整包下发',retry:'重试原共同仓库单',cancel:'截停整包仓库单',reject:'拒绝本条仓库回传',posting:'重新核对实收入账'}}),
  computed:{url(){return this.kind==='EXCHANGE'?`/order/exchanges/${this.owner}/shared-return`:`/order/refunds/business/${this.owner}/shared-returns/${this.source}`},pending(){return this.data.receipts.filter(r=>r.state==='WAIT_ALLOCATION')},totals(){return this.data.members.reduce((n,m)=>{for(const k of ['quantity','accepted_quantity','posted_quantity'])n[k]+=Number(m[k]||0);return n},{quantity:0,accepted_quantity:0,posted_quantity:0})},dispatchLabel(){return ({PENDING:'待下发',SENDING:'提交中',UNKNOWN:'结果未知，请查原单',ACCEPTED:'仓库已接单',FAILED:'仓库下发失败',CANCELED:'已确认截停'})[(this.data.document||{}).dispatch_state]||'待核对'},canAct(){const p=this.$store.getters.permissions||[];return this.data.members.every(m=>p.includes('*:*:*')||p.includes(m.owner_kind==='EXCHANGE'?'order:exchange:execute':'order:refund:goods'))},ready(){return !!this.form.reason&&!!this.form.evidence&&this.form.confirmed_shared&&(this.action!=='allocate'||this.form.allocations.length&&this.form.allocations.every(a=>a.member_id)&&this.rawLines.every((l,i)=>this.assigned(i,'good_qty')===Number(l.good)&&this.assigned(i,'bad_qty')===Number(l.bad)))}},
  mounted(){this.load()},watch:{url(){this.load()}},beforeDestroy(){this.sequence++},methods:{async load(){const seq=++this.sequence;this.loading=true;this.error='';try{const value=(await request({url:this.url})).data;if(seq===this.sequence)this.data=value.bound?value:{bound:false,members:[],receipts:[]}}catch(_){if(seq===this.sequence)this.error='共同退回包裹读取失败，请刷新'}finally{if(seq===this.sequence)this.loading=false}},choices(index){return this.data.members.filter(m=>m.sku_sn===(this.rawLines[index]||{}).sku)},assigned(index,key){return (this.form.allocations||[]).filter(a=>a.line_index===index).reduce((n,a)=>n+Number(a[key]||0),0)},async openAction(action){if(action==='query'){this.busy=true;try{this.data=(await request({url:this.url+'/query',method:'post',data:{}})).data;this.$emit('changed')}finally{this.busy=false}return}this.action=action;this.form={parcel_version:this.data.parcel.control_version,reason:'',evidence:'',confirmed_shared:false,allocations:[]};this.visible=true},openReceipt(receipt){this.action='allocate';let raw=receipt.payload;if(typeof raw==='string')try{raw=JSON.parse(raw)}catch(_){raw={}}this.rawLines=(raw||{}).lines||[];this.form={receipt_id:receipt.id,parcel_version:this.data.parcel.control_version,reason:'',evidence:'',confirmed_shared:false,allocations:this.rawLines.map((l,i)=>({line_index:i,member_id:this.choicesFor(l.sku).length===1?this.choicesFor(l.sku)[0].id:undefined,good_qty:Number(l.good),bad_qty:Number(l.bad)}))};this.visible=true},openRejection(receipt){this.openAction('reject');this.form.receipt_id=receipt.id},choicesFor(sku){return this.data.members.filter(m=>m.sku_sn===sku)},async submit(){if(!this.ready||this.busy)return;this.busy=true;try{this.data=(await request({url:this.url+'/'+this.action,method:'post',data:{...this.form,confirmed:true}})).data;this.visible=false;this.$emit('changed');this.$message.success('已记录共同操作，请核对原仓库结果及各来源库存')}finally{this.busy=false}}}
}
</script>
<style scoped>.shared-return-panel{margin:20px 0;border:1px solid #dfe7f1;padding:18px;border-radius:6px}.heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.heading h3{font-size:15px}.hint{font-size:12px;color:#7b8da2;line-height:1.8}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.summary article{background:#f5f8fc;padding:14px}.summary span{display:block;font-size:12px;color:#7b8da2}.summary strong{display:block;margin-top:8px;font-size:20px}.toolbar{display:flex;align-items:center;gap:12px;margin:16px 0}.el-table .el-select{width:100%}.el-input-number{width:125px}</style>
